// Browser presentation of BattleHUD, WallSampleFX and SSR style 3.
// This module never consumes the match RNG or changes combat state.
import {activated,TACTICS,ATTRS} from './engine.js';
export class BattlePresentation {
  constructor(config,sound){this.config=config;this.sound=sound;this.jobs=new Set();this.animations=new Set();this.reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;this.serial=0;}
  cancel(){this.serial++;for(const job of this.jobs){clearTimeout(job.id);job.done(false);}this.jobs.clear();for(const a of this.animations)a.cancel();this.animations.clear();document.querySelectorAll('.fx-layer').forEach(e=>e.replaceChildren());this.sound.stopEffects();}
  wait(ms){return new Promise(done=>{const job={done,id:setTimeout(()=>{this.jobs.delete(job);done(true);},ms)};this.jobs.add(job);});}
  later(ms,fn){const serial=this.serial;return this.wait(ms).then(ok=>{if(ok&&serial===this.serial)fn();});}
  animate(el,frames,duration,options={}){if(!el)return;const a=el.animate(this.reduced?[{opacity:1},{opacity:1}]:frames,{duration:this.reduced?Math.min(duration,120):duration,easing:'cubic-bezier(.2,.7,.3,1)',...options});this.animations.add(a);a.finished.catch(()=>{}).finally(()=>this.animations.delete(a));return a;}
  root(i){return document.querySelector(`[data-fighter="${i}"]`);}
  card(i){return this.root(i)?.querySelector('.battle-card');}
  layer(i){return this.root(i)?.querySelector('.card-fx');}
  element(parent,cls,text=''){const e=document.createElement('div');e.className=cls;e.textContent=text;parent?.append(e);return e;}
  sprite(parent,file,cls='fx-sprite'){const e=document.createElement('img');e.src=this.config.ui[file];e.alt='';e.className=cls;parent?.append(e);return e;}
  transient(el,frames,seconds,options={}){this.animate(el,frames,seconds*1000,options);this.later(seconds*1000+(options.delay||0)+20,()=>el.remove());return el;}
  ring(i,color='#FFC65C',seconds=.6){const e=this.sprite(this.layer(i),'btl_ring.png','fx-ring');e.style.setProperty('--fx-color',color);this.transient(e,[{transform:'translate(-50%,-50%) scale(.2)',opacity:.9},{transform:'translate(-50%,-50%) scale(1.65)',opacity:0}],seconds);}
  particles(i,color='#FFC65C',count=16,file='btl_star.png',mode='burst',seconds=.8){if(this.reduced)return;for(let n=0;n<count;n++){const a=n*2.39996,d=55+(n%5)*16,e=this.sprite(this.layer(i),file,'fx-particle');e.style.background=color;e.style.setProperty('--fx-color',color);const x=Math.cos(a)*d,y=Math.sin(a)*d;const from=mode==='gather'?`translate(${x}px,${y}px) scale(.3)`:'translate(0,0) scale(1)';const to=mode==='gather'?'translate(0,0) scale(.8)':`translate(${x}px,${y-(mode==='rise'?100:0)}px) rotate(${n*53}deg) scale(.3)`;this.transient(e,[{transform:from,opacity:0},{opacity:1,offset:.2},{transform:to,opacity:0}],seconds,{delay:(n%4)*40});}}
  label(i,text,color='#FFD36B'){const e=this.element(this.layer(i),'effect-label',text);e.style.color=color;this.transient(e,[{transform:'translate(-50%,0) scale(.6)',opacity:0},{transform:'translate(-50%,-12px) scale(1.1)',opacity:1,offset:.25},{transform:'translate(-50%,-35px) scale(1)',opacity:0}],1.2);}
  tint(i,color,seconds=1){const e=this.element(this.layer(i),'fx-tint');e.style.background=color;this.transient(e,[{opacity:0},{opacity:.35,offset:.2},{opacity:0}],seconds);}
  async intro(){const layer=document.querySelector('#screen-fx');const e=this.element(layer,'match-intro');e.innerHTML='<span>あなた</span><b>VS</b><span>CPU</span>';this.animate(e,[{opacity:0,transform:'scale(.7)'},{opacity:1,transform:'scale(1)',offset:.3},{opacity:1,offset:.88},{opacity:0}],this.config.introSeconds*1000);for(let i=0;i<2;i++){this.tiles(i,'appear',1.3);this.particles(i,'#FF9ECF',20,'btl_star.png','gather',1.4);}const ok=await this.wait(this.config.introSeconds*1000);e.remove();return ok;}
  tiles(i,mode,seconds){const image=this.card(i);if(!image||this.reduced)return;const parent=this.layer(i),src=image.src;image.style.opacity='0';for(let n=0;n<48;n++){const x=n%6,y=Math.floor(n/6),e=this.element(parent,'card-tile');Object.assign(e.style,{left:x/6*100+'%',top:y/8*100+'%',width:'16.8%',height:'12.7%',backgroundImage:`url("${src}")`,backgroundSize:'600% 800%',backgroundPosition:`${x/5*100}% ${y/7*100}%`});const drift=`translate(${(x-2.5)*15}px,${30+y*8}px) rotate(${x*11}deg)`;this.transient(e,mode==='appear'?[{opacity:0,transform:drift},{opacity:1,transform:'none'}]:[{opacity:1,transform:'none'},{opacity:0,transform:drift}],seconds,{delay:(mode==='appear'?(47-n):n)*8,fill:'forwards'});}if(mode==='appear')this.later(seconds*1000+400,()=>image.style.opacity='');}
  async showdown(){const layer=document.querySelector('#screen-fx'),e=this.element(layer,'showdown');e.innerHTML='<span>SHOW</span><span>DOWN</span>';const duration=this.config.hud.chargeSeconds*1000;this.animate(e.children[0],[{transform:'translateX(-100%)',opacity:0},{transform:'translateX(0)',opacity:1}],duration*.55);this.animate(e.children[1],[{transform:'translateX(100%)',opacity:0},{transform:'translateX(0)',opacity:1}],duration*.55);this.later(duration*.55,()=>{this.sound.play('showdown',.8);this.animate(e,[{transform:'scale(1.15)'},{transform:'scale(1)'}],250);for(let i=0;i<2;i++)this.particles(i,'#FFF1B8',12);});const ok=await this.wait(duration);e.remove();if(ok)this.sound.play('reveal',.8);return ok;}
  setHP(i,hp,max=1000){const r=this.root(i);if(!r)return;const ratio=Math.max(0,hp/max),track=r.querySelector('.hp-track');r.querySelector('.hp-current').textContent=Math.round(hp);track.setAttribute('aria-valuenow',Math.round(hp));const fill=r.querySelector('.hp-fill');fill.style.width=ratio*100+'%';fill.style.background=this.config.hpColors[ratio>.5?0:ratio>.2?1:2];}
  countdown(i,from,to){const duration=this.config.hud.hpCountdownSeconds*1000,serial=this.serial,start=performance.now();const tick=()=>{if(this.serial!==serial)return;const t=Math.min(1,(performance.now()-start)/duration);this.setHP(i,from+(to-from)*t);if(t<1)requestAnimationFrame(tick);};tick();}
  hit(i,damage,from,to,move){if(damage<=0)return;const heavy=damage>=this.config.hud.dmgTierHeavyMin,strong=damage>=this.config.hud.dmgTierStrongMin;this.sound.play('damage',.8,i===0?-1:1);this.animate(this.root(i),[{transform:'translateX(0)'},{transform:`translateX(${heavy?12:strong?8:5}px)`},{transform:'translateX(-6px)'},{transform:'translateX(0)'}],450);this.tint(i,move===0?'#FF6428':move===1?'#58C858':'#4FB4FF',.35);this.particles(i,move===0?'#FF6428':move===1?'#58C858':'#4FB4FF',heavy?24:14,move===1?'btl_petal.png':'btl_star.png');const e=this.element(this.layer(i),'damage-popup'+(heavy?' heavy':''),'−'+damage);this.transient(e,[{transform:'translate(-50%,10px) scale(.6)',opacity:0},{transform:'translate(-50%,0) scale(1.15)',opacity:1,offset:.12},{transform:'translate(-50%,-12px)',opacity:1,offset:.8},{opacity:0}],this.config.hud.popupSeconds);if(strong)this.label(i,heavy?this.config.hud.heavyLabel:'STRONG!',heavy?'#FF8C26':'#FFF1B8');this.later(this.config.hud.countdownAfterHitSeconds*1000,()=>this.countdown(i,from,to));}
  lunge(i){const direction=i===0?1:-1;this.animate(this.card(i),[{transform:'translate(0,0)'},{transform:'translate(0,-15px) scale(1.05)',offset:.23},{transform:`translate(${direction*55}px,-10px) scale(1.05)`,offset:.53},{transform:'none'}],600);}
  tacticEffect(i,type){const target=[6,8,10].includes(type)?1-i:i;const colors={1:'#FF5F8A',2:'#FF9EC0',3:'#9BE7FF',4:'#9BE7FF',5:'#FFC65C',6:'#8A4CFF',7:'#FFF1B8',8:'#B6BBE8',9:'#FF3B3B',10:'#60C8FF',11:'#FFD36B'};const color=colors[type];this.sound.play(type===3?'reflect':type===6?'poison':[7,8,9,10].includes(type)?'status':'buff',.7,i===0?-1:1);this.tint(target,color);this.ring(target,color);if(type===2||type===9)this.animate(this.card(i),[{transform:'scale(1)'},{transform:`scale(${type===2?1.3:1.08})`},{transform:'scale(1)'}],type===2?1500:1400);if(type===8){for(let n=0;n<3;n++)this.later(n*300,()=>this.label(target,'z','#F4E9D5'));}else if(type===10){const reticle=this.sprite(this.layer(target),'btl_ring_dashed.png','fx-ring');this.transient(reticle,[{transform:'translate(-50%,-50%) scale(1.6) rotate(0deg)',opacity:0},{transform:'translate(-50%,-50%) scale(1) rotate(180deg)',opacity:1,offset:.3},{transform:'translate(-50%,-50%) rotate(270deg)',opacity:0}],1.45);this.label(target,'予告',color);}else{this.particles(target,color,20,type===6?'btl_ring.png':type===1?'btl_tri.png':'btl_star.png',type===11?'gather':'rise',1.4);this.label(target,type===1?'ATK ↑':TACTICS[type],color);}if(type===3){const shield=this.sprite(this.layer(i),'btl_hex_shield.png','fx-shield');this.transient(shield,[{opacity:0,transform:'scale(.7)'},{opacity:.85,transform:'scale(1)',offset:.25},{opacity:0}],.9);const ball=this.element(document.querySelector('#screen-fx'),'counter-ball');const a=this.card(i).getBoundingClientRect(),b=this.card(1-i).getBoundingClientRect(),stage=document.querySelector('.monitor').getBoundingClientRect();ball.style.left=a.left+a.width/2-stage.left+'px';ball.style.top=a.top+a.height/2-stage.top+'px';this.transient(ball,[{transform:'translate(0,0)',opacity:0},{opacity:1,offset:.15},{transform:`translate(${b.left-a.left}px,${b.top-a.top}px)`,opacity:1},{opacity:0}],.45);}}
  showTactic(i,id,data,r){const box=this.root(i).querySelector('.played-tactic');if(id<0){box.innerHTML='<span>戦術なし</span>';return;}box.innerHTML=`<img src="${data.cards[id].image}" alt="${TACTICS[data.cards[id].type]}"><span>判定中</span>`;this.animate(box.querySelector('img'),[{opacity:0,filter:'blur(12px)',transform:'scale(.5)'},{opacity:1,filter:'blur(0)',transform:'scale(1)'}],1400);this.particles(i,'#FFD36B',10,'btl_soft_circle.png','gather');this.later(this.config.tactic.cardFxJudgeDelay*1000,()=>{const success=activated(r,i);box.classList.add(success?'tactic-success':'tactic-failed');box.querySelector('span').textContent=success?'発動':'不発';if(success){this.animate(box.querySelector('img'),[{transform:'scale(1)'},{transform:'scale(1.25)'},{transform:'scale(1)'}],1500);this.tacticEffect(i,data.cards[id].type);}else{this.sound.play('fail',.7);this.animate(box.querySelector('img'),[{filter:'grayscale(0)',opacity:1,clipPath:'inset(0)'},{filter:'grayscale(1)',opacity:.4,clipPath:'inset(0)',offset:.4},{filter:'grayscale(1)',opacity:0,clipPath:'inset(100% 0 0 0)'}],1300,{fill:'forwards'});}});}
  async round(r,data,onReveal){const serial=this.serial;this.later(this.config.tactic.startDelaySeconds*1000,()=>r.used.forEach((id,i)=>this.showTactic(i,id,data,r)));if(!await this.showdown())return false;onReveal();const win=r.roundWinner-1;this.sound.play(win<0?'draw':['fire','leaf','water'][r.moves[win]],.7);const reflected=win>=0&&r.types[1-win]===3&&r.damage[win]>0;for(let i=0;i<2;i++){if(r.damage[1-i]>0&&(!reflected||i===win))this.lunge(i);const delay=reflected&&i===win?this.config.tactic.startDelaySeconds*1000+this.config.tactic.cardFxJudgeDelay*1000+450-this.config.hud.chargeSeconds*1000:320;this.later(delay,()=>this.hit(i,r.damage[i],r.startHp[i],r.hp[i],r.moves[1-i]));}const ok=await this.wait(4300);return ok&&serial===this.serial;}
  async transform(indices,data,state,onFlip){const s=this.config.ssr,serial=this.serial,layer=document.querySelector('#screen-fx'),title=this.element(layer,'transform-title','SSR TRANSFORM');for(const i of indices){const c=this.card(i),card=data.cards[state.sides[i].card],fx=this.layer(i);this.sound.buffer(this.config.voices[card.id]);this.sound.play('transform',.7,i===0?-1:1);this.animate(c,[{transform:'scale(1)'},{transform:'translateY(-14px) scale(1.08)'}],s.floatSeconds*1000,{fill:'forwards'});this.particles(i,s.sparkColor,20,'btl_streak.png','gather',s.floatSeconds);this.later(s.floatSeconds*1000,()=>{this.animate(c,[{filter:'brightness(1)'},{filter:'brightness(0) invert(1)'}],s.whitenSeconds*1000,{fill:'forwards'});this.particles(i,'#FFFFFF',24,'btl_streak.png','gather',s.whitenSeconds);});const flipAt=(s.floatSeconds+s.whitenSeconds+s.chargeHoldSeconds)*1000;this.later(flipAt,()=>{this.sound.play(String(card.id),.7,i===0?-1:1);this.animate(c,[{transform:'translateY(-14px) scale(1.08) rotateY(0)'},{transform:'translateY(-14px) scale(1.08) rotateY(90deg)'}],s.flipSeconds*500,{fill:'forwards'});});this.later(flipAt+s.flipSeconds*500,()=>{c.src=card.backImage;onFlip(i);this.animate(c,[{transform:'translateY(-14px) scale(1.08) rotateY(-90deg)'},{transform:'translateY(-14px) scale(1.12) rotateY(0)'}],s.flipSeconds*500,{fill:'forwards'});});this.later(flipAt+s.flipSeconds*1000,()=>{this.animate(c,[{filter:'brightness(0) invert(1)'},{filter:'brightness(1)'}],s.revealSeconds3*1000,{fill:'forwards'});this.tint(i,s.goldTintColor,s.revealSeconds3);this.ring(i,s.goldTintColor,s.revealSeconds3);this.particles(i,s.goldTintColor,24);});const slamAt=flipAt+(s.flipSeconds+s.revealSeconds3)*1000;this.later(slamAt,()=>{this.animate(c,[{transform:'translateY(-14px) scale(1.08)'},{transform:'scale(.94)'},{transform:'none'}],s.slamSeconds*1000,{fill:'forwards'});this.ring(i,s.shockColor);this.particles(i,'#FFFFFF',26,'btl_petal.png','burst',s.aftermathSeconds);});}const total=(s.floatSeconds+s.whitenSeconds+s.chargeHoldSeconds+s.flipSeconds+s.revealSeconds3+s.slamSeconds+s.aftermathSeconds)*1000;const ok=await this.wait(total);title.remove();return ok&&serial===this.serial;}
  finish(winner){for(let i=0;i<2;i++){if(winner===i+1){this.root(i).classList.add('match-winner');const crown=this.sprite(this.layer(i),'btl_crown.png','winner-crown');this.animate(crown,[{opacity:0,transform:'translate(-50%,-30px) scale(.5)'},{opacity:1,transform:'translate(-50%,0) scale(1)'}],800);this.particles(i,'#FFE08A',24,'btl_star.png','rise',1.6);}else if(winner!==0)this.tiles(i,'lose',1.6);}const e=this.element(document.querySelector('#screen-fx'),'finish-cutin',winner===0?'引き分け':winner===1?'勝利!!':'敗北…');this.transient(e,[{opacity:0,transform:'scale(.7)'},{opacity:1,transform:'scale(1.05)',offset:.1},{opacity:1,offset:.8},{opacity:0,transform:'scale(1)'}],this.config.cutin.finishShowSeconds);}
}
